<style>
    .kb-shell{min-height:100vh;background:#f4f7fb;color:#172033}.kb-wrap{max-width:1240px;margin:auto;padding:30px 22px 70px}.kb-top{display:flex;gap:18px;align-items:flex-start;justify-content:space-between;margin-bottom:22px}.kb-title{font-size:30px;font-weight:900;letter-spacing:-.03em}.kb-muted{color:#64748b}.kb-card{background:#fff;border:1px solid #e3eaf3;border-radius:20px;box-shadow:0 8px 30px rgba(15,23,42,.05)}.kb-pad{padding:22px}.kb-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.kb-item{padding:20px;transition:.18s}.kb-item:hover{transform:translateY(-2px);box-shadow:0 14px 32px rgba(15,23,42,.09)}.kb-row{display:flex;align-items:center;justify-content:space-between;gap:14px}.kb-btn{display:inline-flex;align-items:center;justify-content:center;border-radius:11px;padding:10px 15px;font-weight:800;border:0;cursor:pointer;text-decoration:none}.kb-primary{background:#2563eb;color:#fff}.kb-dark{background:#111827;color:#fff}.kb-soft{background:#eef4ff;color:#2456b8}.kb-danger{background:#fff0f0;color:#dc2626}.kb-input,.kb-select,.kb-textarea{width:100%;border:1px solid #cfd8e6;border-radius:12px;padding:11px 13px;background:#fff}.kb-search{display:flex;gap:10px}.kb-search .kb-input{min-width:300px}.kb-crumb{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-bottom:18px;font-size:14px}.kb-crumb a{color:#2563eb;text-decoration:none;font-weight:800}.kb-stat{font-size:13px;color:#64748b}.kb-icon{width:46px;height:46px;display:grid;place-items:center;border-radius:14px;background:#eef4ff;font-size:23px}.kb-list{display:flex;flex-direction:column;gap:12px}.kb-list-item{padding:16px 18px}.kb-actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.kb-form-grid{display:grid;grid-template-columns:1fr 130px 2fr auto;gap:10px;align-items:center}.kb-form-two{display:grid;grid-template-columns:1fr 2fr auto;gap:10px}.kb-alert{padding:13px 16px;border-radius:12px;margin-bottom:16px;background:#ecfdf5;color:#047857;font-weight:700}.kb-error{padding:13px 16px;border-radius:12px;margin-bottom:16px;background:#fff1f2;color:#be123c}.kb-empty{text-align:center;padding:52px 20px}.kb-pagination nav{margin-top:20px}.kb-badge{display:inline-flex;padding:5px 9px;border-radius:999px;font-size:12px;font-weight:800;background:#eef2ff;color:#4338ca}.kb-published{background:#ecfdf5;color:#047857}.kb-draft{background:#fff7ed;color:#c2410c}.kb-section-head{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-bottom:14px}.kb-editor{display:grid;grid-template-columns:1fr 180px 150px;gap:14px}.kb-editor .wide{grid-column:1/-1}.kb-textarea{min-height:330px;resize:vertical}.kb-modal{margin-bottom:18px}.kb-modal summary{cursor:pointer;list-style:none}.kb-modal summary::-webkit-details-marker{display:none}@media(max-width:900px){.kb-grid{grid-template-columns:1fr 1fr}.kb-form-grid,.kb-form-two,.kb-editor{grid-template-columns:1fr}.kb-search{width:100%}.kb-search .kb-input{min-width:0}.kb-top{flex-direction:column}.kb-actions{justify-content:flex-start}}@media(max-width:600px){.kb-grid{grid-template-columns:1fr}.kb-wrap{padding:20px 12px 50px}.kb-title{font-size:25px}.kb-row{align-items:flex-start;flex-direction:column}}
</style>
